import { Schema, model } from 'mongoose';

/** Sender name used for messages generated by the @ai chatbot */
export const AI_SENDER = 'AI Assistant';

/**
 * messages collection
 * Stores every chat message for history persistence (Special Point).
 * Convert documents with toChatMessage() (services/messageService.ts)
 * before sending them to clients.
 */
const messageSchema = new Schema(
  {
    // R5, R6: the room this message belongs to
    roomId: { type: String, required: true },
    // Username of the sender, or AI_SENDER for bot replies
    sender: { type: String, required: true },
    // Message kind: plain text, image, file attachment, or AI reply
    type: { type: String, enum: ['text', 'image', 'file', 'ai'], default: 'text' },
    // Text content, or a Base64 Data URL for images/files
    content: { type: String, required: true },
    // Original file name (only for image/file messages)
    fileName: { type: String },
    // Read receipts: usernames who have opened and read this message
    readBy: { type: [String], default: [] },
  },
  // Adds createdAt automatically; used to sort chat history
  { timestamps: { createdAt: true, updatedAt: false } },
);

// Compound index so loading a room's history (sorted by time) is fast
messageSchema.index({ roomId: 1, createdAt: 1 });

export const MessageModel = model('Message', messageSchema);
